insert into public.transfer_routes (id, from_program, to_program, ratio_num, ratio_den, min_points, increment, status, verification, max_delay_days, preconditions, source_url, checked_at) values
  ('amex_mr_es-iberia_club', 'amex_mr_es', 'iberia_club', 1, 1, 1000, 1000, 'active', 'UNVERIFIED', 2, array['Your Iberia Club account is in the same name as your Amex card account', 'Your Amex card is issued in Spain (ratios differ by country)', 'Ratio 1:1 is stated on the official Gold and Platinum pages (20,000 MR = 20,000 Iberia Avios; 50,000 MR = 50,000 Avios, checked 27 Oct 2026); the minimum and steps are not confirmed', 'No transfer fee per the official Membership Rewards terms (checked 27 Oct 2026)']::text[], 'https://www.americanexpress.com/es-es/rewards/membership-rewards/terms', null),
  ('ba_club-iberia_club', 'ba_club', 'iberia_club', 1, 1, 1, 1, 'active', 'UNVERIFIED', 0, array['Both accounts are in your name with matching personal details', 'Both accounts are linked through the programme’s “combine Avios” feature, which has its own eligibility rules']::text[], 'https://www.iberia.com/', null),
  ('amex_mr_es-flying_blue', 'amex_mr_es', 'flying_blue', 1, 1, 500, 5, 'active', 'ILLUSTRATIVE', 2, array['Your Flying Blue account is in the same name as your Amex card account']::text[], null, null),
  ('revolut_revpoints-iberia_club', 'revolut_revpoints', 'iberia_club', 1, 1, 1000, 1000, 'active', 'ILLUSTRATIVE', 3, array['Your Revolut plan includes airline-partner transfers']::text[], null, null);
insert into public.card_products (id, name, issuer, country, program, earn, annual_fee_eur, annual_fee_status, notes, source_url, checked_at) values
  ('amex_es_platinum', 'American Express Platinum (Spain)', 'American Express Europe', 'ES', 'amex_mr_es', '[{"category":"all","pointsPerEuro":{"value":1,"status":"VERIFIED","sourceUrl":"https://www.americanexpress.com/es-es/rewards/membership-rewards/terms","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, 780, 'VERIFIED', array['1 Membership Rewards point per €1 on eligible purchases (official MR terms).', 'Fee €65 per month, €780 a year (official Platinum page).', 'Points are credited once purchases are paid and are withdrawn if a purchase is refunded (MR terms).', 'Welcome offer for new cardholders: 5,000 MR for each 30-day month with €1,500 spend, first 10 months (up to 50,000).']::text[], 'https://www.americanexpress.com/es-es/tarjetas-de-cargo/tarjeta-platinum/', '2026-10-27'),
  ('amex_es_gold', 'American Express Gold (Spain)', 'American Express Europe', 'ES', 'amex_mr_es', '[{"category":"all","pointsPerEuro":{"value":0.5,"status":"VERIFIED","sourceUrl":"https://www.americanexpress.com/es-es/rewards/membership-rewards/terms","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}},{"category":"groceries","pointsPerEuro":{"value":0.2,"status":"VERIFIED","sourceUrl":"https://www.americanexpress.com/es-es/rewards/membership-rewards/terms","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, 192, 'VERIFIED', array['1 point per €2 in general and 1 per €5 at Spanish supermarkets (official MR terms).', '1 per €1 applies only at a list of selected travel companies, so it is not assumed for "travel"; add it yourself if your merchant is on the list.', 'Fee €16 per month (official Gold page).', 'Welcome offer for new cardholders: 2,000 MR points for each 30-day month with €1,000 spend, for the first 10 months (up to 20,000).']::text[], 'https://www.americanexpress.com/es-es/tarjetas/tarjetas-de-cargo/tarjeta-gold-card/', '2026-10-27'),
  ('iberia_aire', 'Iberia Aire (Iberia Cards)', 'Iberia Cards', 'ES', 'iberia_club', '[{"category":"all","pointsPerEuro":{"value":0.3333333333333333,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}},{"category":"travel","pointsPerEuro":{"value":0.5,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, 60, 'VERIFIED', array['1 Avios per €3 in general, 1 per €2 on travel and Iberia Club partners, 1 per €1 on Iberia/IAG purchases (official Iberia Cards comparison).', 'Fee €5 per month.', 'Welcome: "up to 15,500 Avios" under the current campaign (ends 31 Oct 2026); its spend conditions are not stated, so it is not planned.']::text[], 'https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/', '2026-10-27'),
  ('iberia_icon', 'Iberia Icon (Iberia Cards)', 'Iberia Cards', 'ES', 'iberia_club', '[{"category":"all","pointsPerEuro":{"value":0.3333333333333333,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}},{"category":"travel","pointsPerEuro":{"value":0.5,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, 118.8, 'VERIFIED', array['1 Avios per €3 in general, 1 per €2 on travel and partners, 1 per €1 on Iberia/IAG purchases (official Iberia Cards comparison).', 'Fee €9.90 per month.', 'Welcome: "up to 20,000 Avios" under the current campaign (ends 31 Oct 2026); spend conditions not stated, so not planned.']::text[], 'https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/', '2026-10-27'),
  ('iberia_zenit', 'Iberia Zenit (Iberia Cards)', 'Iberia Cards', 'ES', 'iberia_club', '[{"category":"all","pointsPerEuro":{"value":1,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/wp/iberia-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}},{"category":"travel","pointsPerEuro":{"value":1,"status":"VERIFIED","sourceUrl":"https://www.iberiacards.es/blog/tu-tarjeta/aire-vs-icon-vs-icon-plus-vs-zenit/","checkedAt":"2026-10-27"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, 948, 'VERIFIED', array['1 Avios per €1 in general, 3 per €1 on Iberia/IAG tickets (official Zenit conditions).', 'Payments with Apple Pay / Google Pay earn Avios only up to €5,000 a month (official Zenit conditions); card payments have no stated cap.', 'Fee €79 per month.', 'Welcome: "up to 40,000 Avios" under the current campaign; spend conditions not stated, so not planned.']::text[], 'https://www.iberiacards.es/wp/iberia-zenit/', '2026-10-27'),
  ('revolut_es', 'Revolut (Spain, RevPoints)', 'Revolut Bank UAB', 'ES', 'revolut_revpoints', '[{"category":"all","pointsPerEuro":{"value":null,"status":"UNKNOWN"},"monthlyCapEur":{"value":null,"status":"UNKNOWN"}}]'::jsonb, null, 'UNKNOWN', array['Earn rate depends on your Revolut plan (from 1 RevPoint per €10 on Standard up to 1 per €1 on Ultra); enter your plan’s rate below.', 'Transferring RevPoints to Iberia Club requires an eligible plan; check your Revolut app.']::text[], 'https://www.revolut.com/es-ES/revpoints/', null);
